export interface LayoutPlusProps {
    logo: React.ReactNode;
    items: MenuItem[];
    value: string;
    onNavigate: (key: string) => void;
    title?: string;
    breadcrumb?: string[];
    actions?: React.ReactNode;
    footer?: React.ReactNode;
    children: React.ReactNode;
    className?: string;
    collapsed?: boolean;
    defaultCollapsed?: boolean;
    onCollapsedChange?: (collapsed: boolean) => void;
    allow?: (item: MenuItem) => boolean;
    route?: {
        pathname: string;
        navigate: (path: string) => void;
    };
    settings?: boolean;
    tabs?: TabItem[];
    onTabsChange?: (tabs: TabItem[]) => void;
    activeTab?: string;
    onTabChange?: (tab: string) => void;
}

export interface MenuItem {
    key: string;
    label: React.ReactNode;
    icon?: React.ReactNode;
    disabled?: boolean;
    children?: MenuItem[];
    href?: string;
    permission?: string;
}

export function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  loading = false,
  children,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    loading?: boolean
  }): React.JSX.Element

export function SheetOverlay({
  className,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Overlay>): React.JSX.Element

export function SheetDescription({
  className,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Description>): React.JSX.Element

export interface UIConfig {
    density: 'comfortable' | 'compact';
    direction: 'ltr' | 'rtl';
    locale: string;
}

export interface ConfigProviderProps extends React.HTMLAttributes<HTMLDivElement> {
    density?: UIConfig['density'];
    direction?: UIConfig['direction'];
    locale?: string;
    accent?: string;
    radius?: number;
}

export function Tabs({
  className,
  orientation = 'horizontal',
  ...props
}: React.ComponentProps<typeof TabsPrimitive.Root>): React.JSX.Element

export function TabsList({
  className,
  variant = 'default',
  ...props
}: React.ComponentProps<typeof TabsPrimitive.List> & VariantProps<typeof tabsListVariants>): React.JSX.Element

export interface TabItem {
    value: string;
    label: React.ReactNode;
    content: React.ReactNode;
    disabled?: boolean;
    closable?: boolean;
}

export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}): readonly [T, (next: T | ((previous: T) => T)) => void]
